var getDecimalValue = function(head) {
    let result = 0;

    // Traverse the linked list from head to tail
    while (head) {
        // Shift current result left by 1 bit (multiply by 2),
        // then append the current binary digit
        result = result * 2 + head.val;

        head = head.next;
    }

    return result;
};
